/*insertMasterMdCmCmsItemChangeReqDt*/
INSERT INTO CMSCATLG_REQ_DT
     ( REQ_NO, REQ_SEQ, JOB_COLUMN, OLD_DATA, NEW_DATA
     , CHANGE_REASON_CODE, CHANGE_REASON_REMARK, ALT_CATLG_ID )
VALUES ( #{st_req_no}, #{st_req_seq}, #{st_job_column}, #{st_old_data}, #{st_new_data}
     , #{st_reason_code}, #{st_reason_remark}, #{st_alt_code} )

