/*selectMasterMdCmCmsItemChangeReqCodeByText*/
SELECT MIN(CODE)
  FROM ICOMCOD1
 WHERE TYPE = #{st_code_type}
   AND FLAG = 'Y'
   AND TRIM(TEXT1) = TRIM(#{st_code_text})


/*selectMasterMdCmCmsItemChangeReqOpenCount*/
SELECT COUNT(*)
  FROM CMSCATLG_REQ
 WHERE CMS_CATLG_ID = #{st_catlg_id}
   AND REQ_STATUS   = 'REQ'
